// =====================================================================
// SOC-Lite · Formatea el informe diario de KPIs y compila el ANALYZE
// =====================================================================
const k = ($input.first() || {}).json || {};
const num = (v) => (v === null || v === undefined || v === '' ? 0 : Number(v));
const pct = (v) => (num(v) * 100).toFixed(1) + ' %';
const sec = (v) => {
  const s = num(v);
  if (!s) return 'n/d';
  if (s < 60) return Math.round(s) + ' s';
  if (s < 3600) return (s / 60).toFixed(1) + ' min';
  return (s / 3600).toFixed(2) + ' h';
};
const flag = (ok) => (ok ? ':white_check_mark:' : ':x:');

const fpRate = num(k.fp_rate);
const reduction = num(k.noise_reduction_rate);
const automation = num(k.automation_rate);
const slaCrit = num(k.sla_compliance_critical);
const slaHigh = num(k.sla_compliance_high);
const targetFp = num(k.target_fp_rate) || 0.3;
const targetRed = num(k.target_noise_reduction) || 0.7;
const targetAuto = num(k.target_automation_rate) || 0.85;

const lines = [
  '*SOC-Lite · KPIs ' + (k.metric_date || '') + '*',
  ':inbox_tray: Alertas ingeridas: *' + num(k.alerts_ingested_raw) + '*  |  triadas: *' + num(k.alerts_triaged) + '*  |  escaladas: *' + num(k.alerts_escalated) + '*',
  ':mag: TP: *' + num(k.alerts_tp) + '*  |  FP: *' + num(k.alerts_fp) + '*  |  suprimidas/deduplicadas: *' + num(k.alerts_suppressed) + '* (eventos colapsados: ' + num(k.duplicates_collapsed) + ')',
  ':stopwatch: MTTT medio: *' + sec(k.mttt_avg_sec) + '*  |  mediana: *' + sec(k.mttt_median_sec) + '*  |  p95: *' + sec(k.mttt_p95_sec) + '*',
  ':hammer: MTTR medio: *' + sec(k.mttr_avg_sec) + '*',
  flag(fpRate <= targetFp) + ' Tasa de FP: *' + pct(fpRate) + '* (objetivo <= ' + pct(targetFp) + ')',
  flag(reduction >= targetRed) + ' Reduction rate: *' + pct(reduction) + '* (objetivo >= ' + pct(targetRed) + ')',
  flag(automation >= targetAuto) + ' Automatizacion: *' + pct(automation) + '* (objetivo >= ' + pct(targetAuto) + ')',
  flag(slaCrit >= 0.95) + ' SLA crítico: *' + pct(slaCrit) + '*  |  ' + flag(slaHigh >= 0.94) + ' SLA alto: *' + pct(slaHigh) + '*'
].join('\n');

const tables = String($env.ANALYZE_TARGETS || $json.ANALYZE_TARGETS || 'soclite.alerts,soclite.triage_results,soclite.incidents,soclite.audit_log,soclite.enrichment_data')
  .split(',')
  .map((t) => t.trim())
  .filter((t) => /^[a-zA-Z_][a-zA-Z0-9_]*\.[a-zA-Z_][a-zA-Z0-9_]*$/.test(t));

const analyzeSql = tables.map((t) => 'ANALYZE ' + t + ';').join('\n');
const rules = {
  fp_rate_ok: fpRate <= targetFp,
  reduction_ok: reduction >= targetRed,
  automation_ok: automation >= targetAuto,
  sla_critical_ok: slaCrit >= 0.95,
  sla_high_ok: slaHigh >= 0.94
};
const breaches = Object.keys(rules).filter((r) => !rules[r]);

return [
  {
    json: Object.assign({}, k, {
      kpi_text: lines,
      kpi_breaches: breaches,
      kpi_ok: breaches.length === 0,
      analyze_targets: tables,
      analyze_sql: analyzeSql,
      slack_channel: $env.KPI_SLACK_CHANNEL || '#soc-metricas',
      calculated_at: new Date().toISOString()
    })
  }
];

