SELECT 'ANALYZE_OK' AS analyze_status,
       now()       AS executed_at,
       (SELECT count(*) FROM pg_stat_user_tables WHERE schemaname = 'soclite' AND last_analyze IS NOT NULL)::int AS tablas_analizadas;
